pub fn solve(
    challenge: &Challenge,
    save_solution: &dyn Fn(&Solution) -> anyhow::Result<()>,
    hyperparameters: &Option<Map<String, Value>>,
    module: Arc<CudaModule>,
    stream: Arc<CudaStream>,
    prop: &cudaDeviceProp,
) -> anyhow::Result<()> {
    solve_with(
        challenge,
        save_solution,
        hyperparameters,
        module,
        stream,
        prop,
        &PARAMS,
        &KERNELS,
    )
}
